<script setup>import{ref,onMounted}from'vue';import PageHeader from'../components/PageHeader.vue';import{queryEntity}from'../api/admin.js';const items=ref([]);onMounted(async()=>items.value=(await queryEntity('production')).data.items)</script><template><div class="admin-page"><PageHeader title="生产管理" description="按订单跟踪工序、计划时间与质检状态"><el-button type="primary">创建生产任务</el-button></PageHeader><div class="work-surface"><div class="filter-bar"><el-input placeholder="任务号 / 订单号" style="width:230px"/><el-select placeholder="全部工序" style="width:140px"><el-option label="封边加工" value="封边加工"/><el-option label="包装" value="包装"/></el-select><el-button type="primary" plain>查询</el-button></div><div class="table-wrap"><el-table :data="items"><el-table-column prop="id" label="任务号" width="120"/><el-table-column prop="order" label="订单号" min-width="160"/><el-table-column prop="customer" label="客户" width="100"/><el-table-column prop="owner" label="负责人" width="100"/><el-table-column prop="process" label="当前工序" width="110"/><el-table-column label="计划时间" width="130"><template #default="{row}">{{row.start}} — {{row.end}}</template></el-table-column><el-table-column label="进度" min-width="180"><template #default="{row}"><el-progress :percentage="row.progress" :stroke-width="7"/></template></el-table-column><el-table-column prop="quality" label="质检" width="100"/><el-table-column label="操作" width="110"><template #default><el-button link type="primary">更新进度</el-button></template></el-table-column></el-table></div></div></div></template>
